/** Eligible hero ids run in picker order and wrap 23 <-> 0. */
export function degeneretteWrapSymbol(symbol) {
  return ((Math.trunc(Number(symbol) || 0) % DEGENERETTE_HERO_COUNT)
    + DEGENERETTE_HERO_COUNT) % DEGENERETTE_HERO_COUNT;
}

/**
 * Symbols a released carousel drag steps by: one per neighbour spacing travelled, at
 * least one once past the threshold, at most `cap` per flick. Dragging left brings the
 * right-hand neighbours in, so it steps forward.
 */
export function degeneretteCarouselSteps(dx, spacing, { threshold = 24, cap = 3 } = {}) {
  const distance = Math.abs(Number(dx) || 0);
  if (distance < threshold) return 0;
  const unit = Number(spacing) > 0 ? Number(spacing) : 60;
  const steps = Math.min(cap, Math.max(1, Math.round(distance / unit)));
  return dx < 0 ? steps : -steps;
}

/** Parse the player-facing decimal without crossing through lossy Number math. */
export function parseDegeneretteAmountInput(value, currency) {
  const match = /^\s*(?:(\d+)(?:\.(\d{0,18}))?|\.(\d{1,18}))\s*$/.exec(String(value ?? ''));
  if (!match) return null;
  try {
    const whole = match[1] || '0';
    const fraction = (match[2] || match[3] || '').padEnd(18, '0');
    const fullScale = (BigInt(whole) * DEGENERETTE_TOKEN_SCALE)
      + BigInt(fraction || '0');
    return Number(currency) === 0 ? fullScale / BigInt(ETH_DIVISOR) : fullScale;
  } catch (_e) {
    return null;
  }
}

/**
 * The wager the contract will actually accept: the parsed amount floored to a
 * whole stake unit (1 gwei-equivalent ETH / 1 whole FLIP). Sub-unit dust would
 * make betDegenerette revert InvalidBet, so it never reaches the wallet.
 */
export function degeneretteDraftAmount(value, currency) {
  const parsed = parseDegeneretteAmountInput(value, currency);
  if (parsed == null) return null;
  return floorDegeneretteStake(parsed, currency);
}

/** Round a computed per-spin wager UP to a whole stake unit (quest targets). */
function _ceilDegeneretteStake(amount, currency) {
  const unit = degeneretteStakeUnit(currency);
  if (unit == null) return null;
  const value = BigInt(amount);
  const rem = value % unit;
  return rem === 0n ? value : value + (unit - rem);
}

function _pendingDegeneretteAmount(amountWei, currency) {
  try {
    const raw = BigInt(amountWei ?? 0);
    if (raw <= 0n) return null;
    const lane = Number(currency);
    const unit = lane === 0 ? 'ETH' : 'FLIP';
    const amount = lane === 0
      ? displayEth(raw, 6)
      : displayTokenSnapped(raw);
    const text = String(amount).includes('.')
      ? String(amount).replace(/0+$/, '').replace(/\.$/, '')
      : String(amount);
    return `${text} ${unit}`;
  } catch (_e) {
    return null;
  }
}

// Two-stage state machine (RESEARCH R5).
const STATE = Object.freeze({
  IDLE: 'idle',
  PLACING: 'placing',
  AWAITING_RNG: 'awaitingRng',
  REQUESTING_RNG: 'requestingRng',
  READY: 'ready',
  RESOLVING: 'resolving',
  INDEXING: 'indexing',
  RESOLVED: 'resolved',
});

export function pendingDegeneretteKey(address) {
  // Bet ids and queue indexes restart on every deployment. Chain id alone is
  // therefore not a safe namespace on testnet: an old run can leave a valid-
  // looking local row that can never resolve against the replacement GAME.
  return `pending-degenerette:${CHAIN.id}:${CHAIN.deployBlock}:${String(address || '').toLowerCase()}`;
}

// The cutoff is the contract's own placement-ordered bet key,
// (index << 64) | betId (degeneretteBetKey) — a bare betId restarts at 1 in
// every RNG index and cannot order a player's bets.
export function clearedDegeneretteThroughKey(address) {
  return `cleared-degenerette-through:${CHAIN.id}:${CHAIN.deployBlock}:${String(address || '').toLowerCase()}`;
}

function _readClearedDegeneretteThrough(address) {
  if (!address || typeof localStorage === 'undefined') return null;
  try {
    const raw = localStorage.getItem(clearedDegeneretteThroughKey(address));
    if (raw == null || raw === '') return null;
    const value = BigInt(raw);
    return value >= 0n ? value : null;
  } catch (_e) {
    return null;
  }
}

function _rememberClearedDegeneretteThrough(address, betKey) {
  if (!address || betKey == null || typeof localStorage === 'undefined') return;
  try {
    const next = BigInt(betKey);
    const current = _readClearedDegeneretteThrough(address);
    if (next < 0n || (current != null && current >= next)) return;
    localStorage.setItem(clearedDegeneretteThroughKey(address), String(next));
  } catch (_e) { /* best-effort browser receipt */ }
}

function _isClearedDegeneretteBet(address, index, betId) {
  const key = degeneretteBetKey(index, betId);
  if (key == null) return false;
  const cutoff = _readClearedDegeneretteThrough(address);
  if (cutoff == null) return false;
  return key <= cutoff;
}

/** Session identity of one bet for one player (betIds restart per index). */
function _betPresentationKey(address, index, betId) {
  if (!address || index == null || betId == null) return null;
  return `${String(address).toLowerCase()}:${String(index)}:${String(betId)}`;
}

function _readPendingBet(address) {
  if (!address || typeof localStorage === 'undefined') return null;
  try {
    const raw = localStorage.getItem(pendingDegeneretteKey(address));
    const row = raw ? JSON.parse(raw) : null;
    if (!row || row.betId == null || row.index == null) return null;
    const betId = BigInt(row.betId);
    if (_isClearedDegeneretteBet(address, row.index, betId)) {
      localStorage.removeItem(pendingDegeneretteKey(address));
      return null;
    }
    let packedData = null;
    let rngWord = 0n;
    try {
      if (row.packedData != null) packedData = BigInt(row.packedData);
    } catch (_e) { packedData = null; }
    try {
      if (row.rngWord != null) rngWord = BigInt(row.rngWord);
    } catch (_e) { rngWord = 0n; }
    let recordStake = 0n;
    try { recordStake = BigInt(row.recordStake ?? 0); } catch (_e) { recordStake = 0n; }
    // Re-decode the receipt rather than retaining an amount cached by an older
    // stake-unit decoder. The packed word is the canonical, boosted wager.
    const bet = dgnDecodePacked(packedData);
    return {
      betId,
      index: BigInt(row.index),
      recordStake,
      currency: bet?.currency ?? Number(row.currency ?? 0),
      amountPerSpin: bet?.amountPerSpin ?? BigInt(row.amountPerSpin ?? 0),
      spinCount: bet?.spinCount || Math.max(1, Number(row.spinCount ?? 1)),
      // Audit a5d4d2cd: one chosen symbol (0..31) replaces the old hero
      // quadrant + full uint32 ticket pair. A row persisted before this
      // rewrite carries neither field this code reads, so it falls back to
      // symbol 0 rather than reinterpret a foreign encoding.
      symbol: Number.isInteger(Number(row.symbol)) ? Number(row.symbol) & 31 : 0,
      packedData,
      rngWord,
      rngRequestPending: Boolean(row.rngRequestPending),
      rngRequestStartedAt: Math.max(0, Number(row.rngRequestStartedAt ?? 0)),
      rngRequestBlock: Math.max(0, Number(row.rngRequestBlock ?? 0)),
      rngObservedBlock: Math.max(0, Number(row.rngObservedBlock ?? 0)),
    };
  } catch (_e) {
    return null;
  }
}

function _writePendingBet(address, row) {
  if (!address || typeof localStorage === 'undefined') return;
  try {
    const key = pendingDegeneretteKey(address);
    if (!row) {
      localStorage.removeItem(key);
      return;
    }
    const payload = {
      betId: String(row.betId),
      index: String(row.index),
      currency: Number(row.currency ?? 0),
      amountPerSpin: String(row.amountPerSpin ?? 0),
      spinCount: Number(row.spinCount ?? 1),
      symbol: Number(row.symbol ?? 0) & 31,
    };
    if (row.packedData != null) payload.packedData = String(row.packedData);
    if (BigInt(row.rngWord ?? 0) !== 0n) payload.rngWord = String(row.rngWord);
    if (BigInt(row.recordStake ?? 0) > 0n) payload.recordStake = String(row.recordStake);
    // Keep old pending-bet records compact, but persist a submitted shared RNG
    // request so its tray card survives a refresh until the word is ready.
    if (row.rngRequestPending) {
      payload.rngRequestPending = true;
      payload.rngRequestStartedAt = Math.max(0, Number(row.rngRequestStartedAt ?? Date.now()));
      if (Number(row.rngRequestBlock) > 0) {
        payload.rngRequestBlock = Math.trunc(Number(row.rngRequestBlock));
      }
      if (Number(row.rngObservedBlock) > 0) {
        payload.rngObservedBlock = Math.trunc(Number(row.rngObservedBlock));
      }
    }
    localStorage.setItem(key, JSON.stringify(payload));
  } catch (_e) { /* private mode: session state still works */ }
}

// Bets displaced from the active slot by a newer placement. Audit 224de529
// settles every bet automatically on the keeper sweep, so an older bet can be
// settled while the panel follows a newer one — and a settled bet is no longer
// in the chain's pending set. Keep the displaced identities (deployment-scoped,
// bounded) so their reveals still play once the active slot frees up.
const UNREVEALED_DEGENERETTE_LIMIT = 20;

export function unrevealedDegeneretteKey(address) {
  return `unrevealed-degenerette:${CHAIN.id}:${CHAIN.deployBlock}:${String(address || '').toLowerCase()}`;
}

function _readUnrevealedBets(address) {
  if (!address || typeof localStorage === 'undefined') return [];
  try {
    const rows = JSON.parse(localStorage.getItem(unrevealedDegeneretteKey(address)) || '[]');
    return Array.isArray(rows) ? rows.filter((row) => row?.betId != null && row?.index != null) : [];
  } catch (_e) {
    return [];
  }
}

function _writeUnrevealedBets(address, rows) {
  if (!address || typeof localStorage === 'undefined') return;
  try {
    const key = unrevealedDegeneretteKey(address);
    const kept = (Array.isArray(rows) ? rows : []).slice(-UNREVEALED_DEGENERETTE_LIMIT);
    if (kept.length === 0) localStorage.removeItem(key);
    else localStorage.setItem(key, JSON.stringify(kept));
  } catch (_e) { /* best-effort browser receipt */ }
}

function _rememberUnrevealedBet(address, row) {
  if (!address || row?.betId == null || row?.index == null) return;
  const key = `${String(row.index)}:${String(row.betId)}`;
  const rows = _readUnrevealedBets(address)
    .filter((entry) => `${String(entry.index)}:${String(entry.betId)}` !== key);
  rows.push({
    betId: String(row.betId),
    index: String(row.index),
    currency: Number(row.currency ?? 0),
    amountPerSpin: String(row.amountPerSpin ?? 0),
    spinCount: Number(row.spinCount ?? 1),
    symbol: Number(row.symbol ?? 0) & 31,
    ...(row.packedData != null ? { packedData: String(row.packedData) } : {}),
    ...(BigInt(row.recordStake ?? 0) > 0n ? { recordStake: String(row.recordStake) } : {}),
  });
  _writeUnrevealedBets(address, rows);
}

function _forgetUnrevealedBet(address, index, betId) {
  if (!address || index == null || betId == null) return;
  const key = `${String(index)}:${String(betId)}`;
  const rows = _readUnrevealedBets(address);
  const kept = rows.filter((entry) => `${String(entry.index)}:${String(entry.betId)}` !== key);
  if (kept.length !== rows.length) _writeUnrevealedBets(address, kept);
}

// ---------------------------------------------------------------------------
// Ticket-picker constants + trait codecs (task #11) — canonical tables live in
// app/app/dgn-traits.js now (shared with the reveal overlay's box-spin reels;
// duplicated decoders are how the f47f106 bit-swap bug shipped).
//
// Canonical trait byte is [QQ][CCC][SSS]: color = bits 5:3, symbol = bits 2:0.
// Result/player tickets (the RESOLVED reels DegeneretteResolved emits)
// still decode the low 6 bits of each byte this way. There is no more
// "customTicket send path" — audit a5d4d2cd replaced the sent full ticket
// with a single chosen `symbol` (0..31); see #dgnSymbol below.
// ---------------------------------------------------------------------------

/**
 * Identity shared with app-box-strip's durable result ledger. Degenerette
 * settles its direct box at index zero, so the settlement transaction hash is
 * the only collision-free key. Carrying it into the reveal lets the overlay
 * suppress and then retire the strip's duplicate presentation action.
 */
export function degeneretteLootboxRelease(player, legs, fallbackTransactionHash = null) {
  const address = String(player || '').toLowerCase();
  const opened = (Array.isArray(legs) ? legs : []).find((leg) => leg?.legType === 'opened');
  if (!address || !opened) return null;
  let index;
  try { index = Number(BigInt(opened.lootboxIndex ?? 0)); } catch (_e) { return null; }
  const transactionHash = String(
    opened.transactionHash || fallbackTransactionHash || '',
  ).toLowerCase();
  const key = lootboxPresentationKey(index, transactionHash);
  if (!key) return null;
  return {
    address,
    key,
    lootboxIndex: index,
    transactionHash: transactionHash || null,
  };
}

/**
 * Stable fallback while a just-mined projection is missing its settlement
 * transaction metadata. One Degenerette bet can award at most one direct
 * lootbox presentation, so player + (index, bet id) collapses the
 * receipt/feed race without merging rewards from different bets. The index
 * is part of the identity: betIds restart at 1 in every RNG index.
 */
export function degeneretteLootboxPresentationId(player, betId, index = null) {
  const address = String(player || '').toLowerCase();
  if (!address || betId == null || String(betId) === '') return null;
  return index == null || String(index) === ''
    ? `degenerette-lootbox:${address}:${String(betId)}`
    : `degenerette-lootbox:${address}:${String(index)}:${String(betId)}`;
}

/**
 * Read enough feed pages to obtain the viewed player's latest resolved bets.
 * Current API workers honour `player`; older workers ignore it and return a
 * global page. Client-side filtering plus the cursor makes both versions safe
 * during a rolling deploy instead of losing a player's round after 200 rows.
 */
export async function fetchDegenerettePlayerFeed(player, {
  betId = null,
  betIndex = null,
  targetResolved = 12,
  maxPages = PLAYER_FEED_MAX_PAGES,
  force = false,
} = {}) {
  const owner = String(player || '').toLowerCase();
  if (!/^0x[0-9a-f]{40}$/.test(owner)) return [];
  const wantedBet = betId == null ? null : String(betId);
  const wantedIndex = betIndex == null ? null : String(betIndex);
  const isWanted = (item) => String(item?.betId) === wantedBet
    && (wantedIndex == null || String(item?.betIndex) === wantedIndex);
  const collected = [];
  const seenCursors = new Set();
  let before = null;

  for (let page = 0; page < Math.max(1, Number(maxPages) || 1); page += 1) {
    const cursor = before == null ? '' : `&before=${encodeURIComponent(String(before))}`;
    const response = await fetchJSON(
      `/degenerette/feed?limit=200&player=${encodeURIComponent(owner)}${cursor}`,
      { force },
    );
    collected.push(...(Array.isArray(response?.items) ? response.items : []));
    const merged = mergeDegeneretteFeedItems(collected)
      .filter((item) => String(item?.player || '').toLowerCase() === owner);
    if (wantedBet != null && merged.some(isWanted)) {
      return merged;
    }
    const resolvedCount = merged.filter((item) => (
      Array.isArray(item?.results)
      && item.results.some((row) => row?.resultType === 'resolved')
    )).length;
    if (wantedBet == null && resolvedCount >= Math.max(1, Number(targetResolved) || 1)) {
      return merged;
    }
    const next = response?.nextCursor;
    if (next == null || seenCursors.has(String(next))) return merged;
    seenCursors.add(String(next));
    before = next;
  }
  return mergeDegeneretteFeedItems(collected)
    .filter((item) => String(item?.player || '').toLowerCase() === owner);
}

/**
 * Pick the first complete upcoming-draw ticket carrying gold, falling back to
 * the first complete ticket. The returned shape matches the editor's {s,c}
 * state and makes the first eligible gold quadrant Hero. Dice cannot be heroes.
 */
export function selectDegeneretteDefaultTicket(payload) {
  const candidates = [];
  const cards = Array.isArray(payload?.cards) ? payload.cards : [];
  for (const traitIds of dgnReconstructTicketTraits(cards)) {
    const quadrants = dgnTraitIdsToQuadrants(traitIds);
    if (!quadrants.every(Boolean)) continue;
    const goldAt = quadrants.findIndex((trait, q) => q < DEGENERETTE_HERO_COUNT / 8 && trait?.col === 7);
    candidates.push({
      cardIndex: candidates.length,
      hasGold: goldAt >= 0,
      hero: goldAt >= 0 ? goldAt : 0,
      traits: quadrants.map((trait) => ({ s: trait.sym, c: trait.col })),
    });
  }
  return candidates.find((ticket) => ticket.hasGold) || candidates[0] || null;
}

export function degeneretteDeitySymbolForOwner(catalog, owner) {
  const address = String(owner || '').toLowerCase();
  if (!address || !(catalog?.ownersBySymbol instanceof Map)) return null;
  for (const [symbolId, symbolOwner] of catalog.ownersBySymbol.entries()) {
    const id = Number(symbolId);
    if (String(symbolOwner || '').toLowerCase() === address
      && Number.isInteger(id)
      && id >= 0
      && id < DEGENERETTE_HERO_COUNT) {
      return id;
    }
  }
  return null;
}

