  connectedCallback() {
    if (this.#initialized) {
      this.#mountReferralStrip();
      this.#watchPlaceLabel();
      const stage = this.querySelector('[data-bind="dgn-symbol-stage"]');
      const bezel = this.querySelector('.dgn-symbol-preview__art');
      if (stage) this.#carouselResizeObserver?.observe(stage);
      if (bezel) this.#carouselResizeObserver?.observe(bezel);
      return;
    }
    this.#initialized = true;
    this.#renderShell();
    this.#restoreBetPreference(this.#draftCurrency);
    this.#wireEventHandlers();
    this.#mountReferralStrip();
    this.#wireVisibilityRePoll();
    this.#wireStoreSubscriptions();
    this.#unsubs.push(subscribeUiPreferences(({ name, value }) => {
      if (name !== 'lightweightMode') return;
      if (value) this.#pollController?.abort();
      else void this.#runPollCycle();
    }));
    if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
      document.addEventListener(DGN_TICKET_COPY_EVENT, this.#ticketCopyListener);
      document.addEventListener('quest:activate', this.#questActivateListener);
      document.addEventListener('quest:open', this.#referralQuestListener);
      document.addEventListener(DEITY_ART_UPDATED_EVENT, this.#deityArtUpdated);
    }
    this.#startPolling();
    this.#restorePendingBet();
    this.#renderState();
    this.#renderCurrencyGate();
    this.#renderBetLimits();
    this.#watchPlaceLabel();
    this.#refreshReferralLink();
    this.#runPollCycle();
  }

  disconnectedCallback() {
    this.#unmountReferralStrip();
    this.#closeReferralDialog();
    this.#showBoonPopover(false);
    document.removeEventListener('pointerdown', this.#boonPopoverOutside);
    document.removeEventListener('keydown', this.#boonPopoverOutside);
    this.#deityPresentationSeq += 1;
    this.#deityPresentationRequest = null;
    this.#deityOwnerSeq += 1;
    this.#closeSymbolDialog();
    this.#closeBasicsDialog();
    this.#carouselDrag = null;
    this.#stopCarousel();
    this.#carouselResizeObserver?.disconnect();
    this.#carouselGeometry = null;
    this.#placeResizeObserver?.disconnect();
    if (this.#placeFitFrame != null) this.ownerDocument?.defaultView?.cancelAnimationFrame?.(this.#placeFitFrame);
    this.#placeFitFrame = null;
    this.#placeResizeObserver = null;
    this.#placeWidth = null;
    this.#clearCarouselClickGuard();
    clearTimeout(this.#carouselWheel.timer);
    this.#persistBetPreference(this.#draftCurrency);
    this.#pendingRecoverySeq += 1;
    this.#pendingRecoveryAddress = null;
    this.#resolutionGeneration += 1;
    if (typeof this.#pollHandle === 'function') {
      try { this.#pollHandle(); } catch (_) { /* defensive */ }
      this.#pollHandle = null;
    }
    if (this.#pollController) {
      try { this.#pollController.abort(); } catch (_) { /* defensive */ }
      this.#pollController = null;
    }
    this.#cancelRngPoll();
    if (this.#visibilityListener
      && typeof document !== 'undefined'
      && typeof document.removeEventListener === 'function') {
      try { document.removeEventListener('visibilitychange', this.#visibilityListener); }
      catch (_) { /* defensive */ }
    }
    this.#visibilityListener = null;
    if (typeof document !== 'undefined' && typeof document.removeEventListener === 'function') {
      try { document.removeEventListener(DGN_TICKET_COPY_EVENT, this.#ticketCopyListener); }
      catch (_) { /* defensive */ }
      try { document.removeEventListener('quest:activate', this.#questActivateListener); }
      catch (_) { /* defensive */ }
      try { document.removeEventListener('quest:open', this.#referralQuestListener); }
      catch (_) { /* defensive */ }
      document.removeEventListener(DEITY_ART_UPDATED_EVENT, this.#deityArtUpdated);
    }
    clearPendingActions(PENDING_SOURCE);
    if (this.#errorTimer != null) {
      try { clearTimeout(this.#errorTimer); } catch (_) { /* defensive */ }
      this.#errorTimer = null;
    }
    this.#referralResolveSeq += 1;
    if (this.#referralCopyTimer != null) {
      try { clearTimeout(this.#referralCopyTimer); } catch (_) { /* defensive */ }
      this.#referralCopyTimer = null;
    }
    this.#clearReferralCoinWatchdog();
    for (const u of this.#unsubs) {
      try { u(); } catch (_e) { /* defensive */ }
    }
    this.#unsubs = [];
  }

  #mountReferralStrip() {
    if (typeof document === 'undefined' || typeof document.querySelector !== 'function') return;
    const strip = document.querySelector('[data-referral-strip]');
    const card = this.#referralCard ?? this.querySelector('.deg-referral-card');
    if (!strip || !card) return;
    if (!this.#referralCard) {
      this.#referralCard = card;
      this.#referralCardHome = { parent: card.parentNode, next: card.nextSibling };
    }
    if (card.parentNode !== strip) strip.appendChild(card);
    strip.hidden = false;
    this.classList?.add('has-referral-strip');
  }

  #unmountReferralStrip() {
    const card = this.#referralCard;
    const home = this.#referralCardHome;
    if (!card || !home?.parent || card.parentNode === home.parent) return;
    const strip = card.parentNode;
    const next = home.next && home.next.parentNode === home.parent ? home.next : null;
    home.parent.insertBefore(card, next);
    if (strip) strip.hidden = true;
    this.classList?.remove('has-referral-strip');
  }

  /** A referral-card part, whether the card is in the panel or moved to the strip. */
  #referralQuery(selector) {
    return this.querySelector(selector)
      ?? this.#referralCard?.querySelector?.(selector)
      ?? (this.#referralDialog?.matches?.(selector) ? this.#referralDialog : null)
      ?? this.#referralDialog?.querySelector?.(selector) ?? null;
  }

